const knowledgeBase={articles:[{id:"327",title:"Traffic Rules / Yol Qaydaları",content:[{v:"Not following road signs / Yol nişanlarına riayət edilməməsi",f:40,p:0},{v:"Running red light / Qırmızı işıqda keçmə",f:100,p:3},{v:"Driving in bicycle lanes",f:100,p:2},{v:"Railway crossing violations",f:100,p:4},{v:"Wrong-way on one-way street",f:150,p:4}]},{id:"328",title:"Speeding / Sürət aşması",content:[{v:"10-20 km/h over limit",f:10,p:0},{v:"21-40 km/h over limit",f:50,p:2},{v:"41-60 km/h over limit",f:200,p:3},{v:"61+ km/h over limit",f:300,p:4}]},{id:"329",title:"Safety / Təhlükəsizlik",content:[{v:"No seatbelt / Kəmər bağlamamaq",f:40,p:0},{v:"No helmet (motorcycle) / Dəbilqəsiz",f:40,p:0},{v:"Improper lights use",f:30,p:0}]},{id:"330",title:"Pedestrians / Piyadalar",content:[{v:"Not yielding at crosswalk",f:50,p:0},{v:"Not yielding when turning",f:50,p:0}]},{id:"331",title:"Emergency Vehicles",content:[{v:"Not yielding to emergency vehicles",f:100,p:3}]},{id:"332",title:"No License / Lisenziyasız",content:[{v:"No power of attorney",f:40,p:0},{v:"Driving without license",f:200,p:0},{v:"No license (repeat)",f:400,p:0},{v:"No license + damage",f:500,p:"1mo detention"}]},{id:"333",title:"DUI / Alkoqol",content:[{v:"Driving under influence",f:400,p:"License 6mo-1yr"},{v:"DUI repeat",f:500,p:"License 2yr+15d detention"},{v:"DUI + damage",f:700,p:"License 2yr+detention"}]},{id:"334",title:"No License + DUI",content:[{v:"No license + drunk",f:500,p:"15d detention"},{v:"No license + drunk + damage",f:800,p:"1-2mo detention"}]},{id:"342",title:"Vehicle Issues",content:[{v:"Operation rules violation",f:40,p:0},{v:"Technical condition violation",f:150,p:0},{v:"Loud exhaust",f:500,p:0},{v:"Loud exhaust (repeat)",f:1000,p:0},{v:"License plate violation",f:100,p:4}]},{id:"343",title:"Refusing Test / Müayinədən imtina",content:[{v:"Refusing sobriety test",f:400,p:"License 6mo-1yr"},{v:"Refusing test (repeat)",f:500,p:"License 2yr+15d"}]},{id:"346",title:"Stopping / Dayanma",content:[{v:"General stopping violation",f:20,p:0},{v:"Stopping at bus stop",f:40,p:2},{v:"Blocking public transport",f:100,p:4},{v:"Double parking",f:80,p:2},{v:"Near intersection",f:40,p:2},{v:"In bike lane",f:100,p:2},{v:"In bus lane",f:100,p:2},{v:"On sidewalk",f:60,p:2}]},{id:"346-1",title:"Parking / Parklanma",content:[{v:"Exceeding paid parking",f:20,p:0},{v:"Improper parking",f:20,p:0},{v:"Disabled spot violation",f:60,p:0},{v:"Over 24h parking",f:20,p:0}]},{id:"469",title:"Insurance / Sığorta",content:[{v:"No insurance (individual)",f:50,p:0},{v:"No insurance (official)",f:100,p:0},{v:"No insurance (company)",f:300,p:0}]},{id:"511",title:"Hooliganism / Xuliqanlıq",content:[{v:"Racing/wheelies/burnouts",f:"500-750",p:"License 1yr+detention"},{v:"Hooliganism (repeat)",f:"750-1000",p:"License 2yr+1-2mo"},{v:"Racing 60+ over",f:"2000-4000",p:"License 2yr+detention"}]}]};

const msg = $input.first().json.message;
if (!msg || !msg.text) return {json: {skip: true}};

const userMessage = msg.text;
const chatId = msg.chat.id;
const q = userMessage.toLowerCase();

const kw = {
  'speed':['328'],'sürət':['328'],'fast':['328'],
  'alcohol':['333','334'],'alkoqol':['333','334'],'drunk':['333','334'],'sərxoş':['333'],
  'license':['332'],'lisenziya':['332'],
  'seatbelt':['329'],'kəmər':['329'],'belt':['329'],'helmet':['329'],
  'parking':['346-1'],'parklanma':['346-1'],'dayanma':['346'],'stop':['346'],
  'pedestrian':['330'],'piyada':['330'],
  'red light':['327'],'qırmızı':['327'],'svetofor':['327'],
  'insurance':['469'],'sığorta':['469'],
  'emergency':['331'],'test':['343'],'müayinə':['343'],
  'exhaust':['342'],'səs':['342'],
  'racing':['511'],'yarış':['511'],'drift':['511'],'wheelie':['511']
};

const matched = new Set();
for (const [k, ids] of Object.entries(kw)) {
  if (q.includes(k)) ids.forEach(id => matched.add(id));
}

if (matched.size === 0) {
  for (const a of knowledgeBase.articles) {
    if (q.split(' ').filter(w => w.length > 3).some(w => JSON.stringify(a).toLowerCase().includes(w))) {
      matched.add(a.id);
    }
  }
}

const results = knowledgeBase.articles.filter(a => matched.has(a.id)).slice(0, 3);
if (results.length === 0) {
  results.push(knowledgeBase.articles[1], knowledgeBase.articles[2]);
}

let ctx = "AZERBAIJAN TRAFFIC FINES:";
for (const a of results) {
  ctx += ` ${a.title}:`;
  for (const i of a.content) {
    ctx += ` ${i.v}: ${i.f} AZN${i.p ? `, ${i.p} pts` : ''};`;
  }
}

// Build the request body for Groq
const requestBody = {
  model: "llama-3.1-8b-instant",
  messages: [
    {
      role: "system",
      content: "You answer questions about Azerbaijan traffic fines. Reply in the same language as the question (English or Azerbaijani). Be concise. Always state fine in AZN and penalty points."
    },
    {
      role: "user",
      content: ctx + " Question: " + userMessage
    }
  ],
  temperature: 0.3,
  max_tokens: 400
};

return {
  json: {
    userMessage,
    chatId,
    context: ctx,
    requestBody
  }
};

const resp = $input.first().json;
if (resp.choices && resp.choices[0]) {
  return { json: { text: resp.choices[0].message.content } };
}
return { json: { text: "Sorry, I could not process your request." } };
